From 56ee01c7625d90382f958e31d376366ddeb7de47 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:41:47 +0100
Subject: [PATCH] applets/kimpanel: switch input method with the mouse wheel

Scrolling over the input method icon did nothing, while other panel
widgets like the pager use the wheel to switch. Now it asks the input
method for its list and activates the next or previous entry instead.

BUG: 340606
---
 applets/kimpanel/qml/StatusIcon.qml | 11 ++++++++
 applets/kimpanel/qml/main.qml       | 43 +++++++++++++++++++++++++++++
 2 files changed, 54 insertions(+)

diff --git a/applets/kimpanel/qml/StatusIcon.qml b/applets/kimpanel/qml/StatusIcon.qml
index 35d395066e..a9342cc0d6 100644
--- a/applets/kimpanel/qml/StatusIcon.qml
+++ b/applets/kimpanel/qml/StatusIcon.qml
@@ -18,6 +18,9 @@ Item {
     required property string hint

     signal triggered(int /*Qt::MouseButton*/ button)
+    signal scrolled(int steps)
+
+    property int wheelDelta: 0

     readonly property int iconSize: Kirigami.Units.iconSizes.roundedIconSize(Math.min(width, height))

@@ -67,6 +70,14 @@ Item {
         onClicked: mouse => {
             statusIcon.triggered(mouse.button);
         }
+        onWheel: wheel => {
+            statusIcon.wheelDelta += wheel.angleDelta.y || wheel.angleDelta.x;
+            const steps = Math.trunc(statusIcon.wheelDelta / 120);
+            if (steps !== 0) {
+                statusIcon.wheelDelta -= steps * 120;
+                statusIcon.scrolled(-steps);
+            }
+        }

         PlasmaCore.ToolTipArea {
             anchors.fill: parent
diff --git a/applets/kimpanel/qml/main.qml b/applets/kimpanel/qml/main.qml
index c947fb404c..b055ef5426 100644
--- a/applets/kimpanel/qml/main.qml
+++ b/applets/kimpanel/qml/main.qml
@@ -147,6 +147,7 @@ PlasmoidItem {
                             contextMenu.open(statusIcon, {key: delegate.key, label: delegate.label});
                         }
                     }
+                    onScrolled: steps => kimpanel.switchInputMethod(delegate.key, delegate.label, delegate.tip, steps)
                 }
             }
         }
@@ -175,6 +176,44 @@ PlasmoidItem {
         timer.restart();
     }

+    property var pendingSwitch: null
+
+    function switchInputMethod(key, label, tip, steps) {
+        if (key !== "/Fcitx/im" && key !== "/IBus/Logo") {
+            return;
+        }
+        if (pendingSwitch) {
+            pendingSwitch.steps += steps;
+            return;
+        }
+        pendingSwitch = {label, tip, steps};
+        pendingSwitchTimer.restart();
+        helper.triggerProperty(key);
+    }
+
+    function finishSwitch(menuData) {
+        const request = pendingSwitch;
+        pendingSwitch = null;
+        pendingSwitchTimer.stop();
+        if (menuData.length === 0) {
+            return;
+        }
+        let current = menuData.findIndex(prop => prop.hint.split(",").includes("checked"));
+        if (current === -1) {
+            current = menuData.findIndex(prop => prop.label === request.label || prop.label === request.tip
+                                                 || prop.label.endsWith(" - " + request.tip));
+        }
+        const count = menuData.length;
+        const next = ((Math.max(current, 0) + request.steps) % count + count) % count;
+        helper.triggerProperty(menuData[next].key);
+    }
+
+    Timer {
+        id: pendingSwitchTimer
+        interval: 1000
+        onTriggered: kimpanel.pendingSwitch = null
+    }
+
     function showMenu(menu, menuData) {
         const actionList = [];
         for (const /*KimpanelProperty*/ prop of menuData) {
@@ -269,6 +308,10 @@ PlasmoidItem {
             timer.restart();
         }
         function onMenuTriggered(menu) {
+            if (kimpanel.pendingSwitch) {
+                kimpanel.finishSwitch(menu);
+                return;
+            }
             kimpanel.showMenu(actionMenu, menu);
         }
     }
-- 
